/**
 * Platform HEIC decoder the app implements (ImageIO on iOS).
 */
public protocol HeicDecoder: AnyObject, Sendable {
    
    /**
     * Decode `path` to oriented RGB. The implementation opens the file
     * itself — do not call back into the core.
     */
    func decode(path: String) throws  -> HostDecodedImage
    
}
/**
 * Platform HEIC decoder the app implements (ImageIO on iOS).
 */
open class HeicDecoderImpl: HeicDecoder, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_gallery_ffi_fn_clone_heicdecoder(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_gallery_ffi_fn_free_heicdecoder(handle, $0) }
    }

    

    
    /**
     * Decode `path` to oriented RGB. The implementation opens the file
     * itself — do not call back into the core.
     */
open func decode(path: String)throws  -> HostDecodedImage  {
    return try  FfiConverterTypeHostDecodedImage_lift(try rustCallWithError(FfiConverterTypeHeicDecodeError_lift) {
        uniffiCallStatus in
    uniffi_gallery_ffi_fn_method_heicdecoder_decode(
            self.uniffiCloneHandle(),
        FfiConverterString.lower(path),uniffiCallStatus
    )
})
}
    

    
}



// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceHeicDecoder {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceHeicDecoder = UniffiVTableCallbackInterfaceHeicDecoder(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeHeicDecoder.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface HeicDecoder: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeHeicDecoder.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface HeicDecoder: handle missing in uniffiClone")
            }
        },
        decode: { (
            uniffiHandle: UInt64,
            path: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> HostDecodedImage in
                guard let uniffiObj = try? FfiConverterTypeHeicDecoder.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.decode(
                     path: try FfiConverterString.lift(path)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeHostDecodedImage_lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeHeicDecodeError_lower
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceHeicDecoder> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceHeicDecoder>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitHeicDecoder() {
    uniffi_gallery_ffi_fn_init_callback_vtable_heicdecoder(UniffiCallbackInterfaceHeicDecoder.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHeicDecoder: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<HeicDecoder>()

    typealias FfiType = UInt64
    typealias SwiftType = HeicDecoder

    public static func lift(_ handle: UInt64) throws -> HeicDecoder {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return HeicDecoderImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: HeicDecoder) -> UInt64 {
         if let rustImpl = value as? HeicDecoderImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HeicDecoder {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: HeicDecoder, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeHeicDecoder_lift(_ handle: UInt64) throws -> HeicDecoder {
    return try FfiConverterTypeHeicDecoder.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeHeicDecoder_lower(_ value: HeicDecoder) -> UInt64 {
    return FfiConverterTypeHeicDecoder.lower(value)
}






/**
 * The photo table and every index over it: the sorted order, the search
 * corpus, and the tag buckets.
 *
 * One instance per Store, rebuilt wholesale from `allPhotos` after every
 * `apply(_:)` — the same contract `SearchIndex.build(allPhotos:)` and
 * `TagIndex.build(allPhotos:)` had. Partial updates were never part of it.
 */
public protocol LibraryIndexProtocol: AnyObject, Sendable {
    
    /**
     * Rebuild every index from `photos` and return the results the app needs
     * straight away.
     *
     * Takes the photos by value: they become the index's photo table, so
     * nothing is copied after the boundary crossing itself.
     */
    func build(photos: [ScannedMediaHost])  -> LibraryBuildStructure
    
    /**
     * Rebuild and retain the platform's per-photo UTC offsets.
     *
     * The offsets are supplied on the same once-per-library crossing as the
     * photos. Scheduled memories then reuse both tables instead of rebuilding
     * and re-marshalling a second 20,000-photo generation snapshot.
     */
    func buildWithTimeZoneOffsets(photos: [ScannedMediaHost], photoTimeZoneOffsets: [Int32])  -> LibraryBuildStructure
    
    /**
     * Collections hub for non-People tag namespaces (Objects, Scenes, Places,
     * Albums, Events, Other — as present). Item ids are tag ids.
     *
     * People are not a collection section; use [`Self::people_structure`].
     * Memories are omitted until 5.6: the index does not store a
     * `MemoryStructure` id list. The shell caches the last
     * [`generate_memories`] / [`MemoryGenerator`] result and drills in with
     * [`Self::set_photo_ids_view`].
     *
     * iOS has no Swift caller for this window yet (Phase 5.2 explicit deferral).
     */
    func collectionStructure()  -> ViewStructure
    
    /**
     * Display-ready collection rows for one namespace section.
     *
     * iOS has no Swift caller for this window yet (Phase 5.2 explicit deferral).
     */
    func collectionWindow(sectionId: String, offset: UInt64, limit: UInt64, generation: UInt64) throws  -> [GalleryTextRow]
    
    /**
     * Compute the widget's scheduled horizon over the library table already
     * retained by this index.
     *
     * Only the small platform context crosses per run. Photo records and
     * capture-time offsets crossed once, at build.
     */
    func computeScheduled(context: ScheduledMemoryContext, horizonDays: Int64, hiddenMemoryIds: [String])  -> [ScheduledMemoryStructure]
    
    /**
     * This folder's own photos (the scan slice), so a shell can
     * [`Self::set_photo_ids_view`]. Recursive totals stay on the text-row
     * trailing from `total_photo_count`.
     *
     * iOS has no Swift caller for this window yet (Phase 5.2 explicit deferral).
     */
    func folderPhotoIds(folderId: String)  -> [String]
    
    /**
     * Folder listing for one parent. `None` is children of the scan root; a
     * single library root is not shown as a row.
     *
     * Section id is `folders`, slot kind is a text row, item ids are child
     * folder ids. Changing `parent_id` bumps [`Self::view_generation`] so a
     * window cannot join rows to an older listing.
     *
     * iOS has no Swift caller for this window yet (Phase 5.2 explicit deferral).
     */
    func folderStructure(parentId: String?)  -> ViewStructure
    
    /**
     * Display-ready folder rows for the listing last returned by
     * [`Self::folder_structure`].
     *
     * Title is the folder name. Trailing is the recursive photo count
     * (`total_photo_count`) as `"1 photo"` / `"N photos"`. Subtitle is the
     * path leaf when it differs from the name.
     *
     * iOS has no Swift caller for this window yet (Phase 5.2 explicit deferral).
     */
    func folderWindow(sectionId: String, offset: UInt64, limit: UInt64, generation: UInt64) throws  -> [GalleryTextRow]
    
    /**
     * People listing. Item ids come from the cached `People` suggestions.
     *
     * Person photos already work via [`Self::photo_ids_for_tag`] (`full_path`)
     * plus [`Self::set_photo_ids_view`].
     *
     * iOS has no Swift caller for this window yet (Phase 5.2 explicit deferral).
     */
    func peopleStructure()  -> ViewStructure
    
    /**
     * Display-ready people rows (`display_name`, trailing count).
     *
     * iOS has no Swift caller for this window yet (Phase 5.2 explicit deferral).
     */
    func peopleWindow(sectionId: String, offset: UInt64, limit: UInt64, generation: UInt64) throws  -> [GalleryTextRow]
    
    /**
     * How many photos the index currently holds. Cheap; used by the app's
     * "did the rebuild I am waiting on actually land" assertions and by tests.
     */
    func photoCount()  -> UInt32
    
    /**
     * `TagIndex.photos(forTag:)` — the photos credited to `full_path`,
     * including the `Places/…` prefix expansion, in `allPhotos` order.
     */
    func photoIdsForTag(fullPath: String)  -> [String]
    
    /**
     * Current Photos-screen structure without changing search intent.
     */
    func photoStructure()  -> ViewStructure
    
    /**
     * Display-ready photos for one visible window.
     */
    func photoWindow(sectionId: String, offset: UInt64, limit: UInt64, generation: UInt64) throws  -> [GalleryMediaItem]
    
    /**
     * Rebuild every index from `photos` and return the results the app needs
     * straight away.
     */
    func rebuild(photos: [ScannedMediaHost], photoTimeZoneOffsets: [Int32])  -> LibraryBuildStructure
    
    /**
     * Number of photos the scheduled-horizon reuse path currently owns.
     */
    func scheduledPhotoCount()  -> UInt32
    
    /**
     * `SearchIndex.search(query:requiredTags:allTags:)`, in sorted order.
     *
     * Required tags arrive as plain paths rather than as whole suggestions:
     * the only two fields the Swift read off a `TagSuggestion` here were
     * `fullPath` and `namespace`, and the second is the first's leading
     * segment. Re-deriving it removes a record from the wire and a way for the
     * two to disagree.
     */
    func search(query: String, requiredTagPaths: [String])  -> [String]
    
    /**
     * Install the scanner's flat folder list and the photo-id order those
     * slices address.
     *
     * Extending [`Self::build`] would break existing `build(photos)` callers,
     * so folders arrive on this second call after a scan or snapshot load.
     * The recursive `PhotoFolder` tree is not stored and never returned.
     *
     * iOS has no Swift caller for this window yet (Phase 5.2 explicit deferral).
     */
    func setFolders(folders: [ScannedFolderHost], photoIdsInScanOrder: [String]) 
    
    /**
     * Apply an id-only drill-in intent (folder, memory, or saved selection).
     *
     * The shell supplies structure ids, never photo records. Unknown/removed
     * ids are dropped and the caller's order is preserved.
     */
    func setPhotoIdsView(viewId: String, photoIds: [String], query: String, requiredTagPaths: [String])  -> ViewStructure
    
    /**
     * Apply Photos-screen search/tag intent and return cheap structure.
     *
     * The whole ordered id list is structure by ADR 0003 R4. The records
     * behind those ids are fetched only through [`Self::photo_window`].
     */
    func setPhotoView(query: String, requiredTagPaths: [String])  -> ViewStructure
    
    /**
     * The date-descending photo order. Backs `store.sortedPhotos`.
     */
    func sortedPhotoIds()  -> [String]
    
    /**
     * Tag-picker structure. The list is ids only; labels and counts are
     * returned by [`Self::tag_window`].
     */
    func tagStructure()  -> ViewStructure
    
    /**
     * The aggregated tag list and the `People/…` subset — the same pair
     * [`Self::build`] returned, for a caller that has lost it.
     */
    func tagSuggestions()  -> TagStructures
    
    /**
     * Display-ready tag rows for one visible window.
     */
    func tagWindow(sectionId: String, offset: UInt64, limit: UInt64, generation: UInt64) throws  -> [GalleryTextRow]
    
    /**
     * Generation currently guarding every library window.
     */
    func viewGeneration()  -> UInt64
    
}
/**
 * The photo table and every index over it: the sorted order, the search
 * corpus, and the tag buckets.
