/**
 * Where a cluster stands with the user.
 */

public enum ClusterState: Equatable, Hashable {
    
    /**
     * Nobody has named it — the review queue.
     */
    case unlabeled
    /**
     * A person's name is attached; new faces joining it are auto-tagged.
     */
    case named
    /**
     * A real face the user does not want to name (passer-by, poster).
     */
    case ignored
    /**
     * The user said "not a person" / "not a face".
     */
    case rejected





}

#if compiler(>=6)
extension ClusterState: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeClusterState: FfiConverterRustBuffer {
    typealias SwiftType = ClusterState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ClusterState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .unlabeled
        
        case 2: return .named
        
        case 3: return .ignored
        
        case 4: return .rejected
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ClusterState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .unlabeled:
            writeInt(&buf, Int32(1))
        
        
        case .named:
            writeInt(&buf, Int32(2))
        
        
        case .ignored:
            writeInt(&buf, Int32(3))
        
        
        case .rejected:
            writeInt(&buf, Int32(4))
        
        }
    }
}


