/**
 * Why a face call failed.
 *
 * A flattening of [`MlError`] plus the one failure mode only this layer has,
 * [`FaceError::AlreadyRunning`]. The `detail` strings are for logs — the
 * *variant* is what callers switch on.
 */
public 
enum FaceError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The pack loaded but ships no face models.
     *
     * Not a broken pack: a tagging-only pack is valid, and the app's answer is
     * to hide the faces controls.
     */
    case ModelsUnavailable
    /**
     * A file named by the model-pack manifest is missing.
     */
    case PackFileMissing(
        /**
         * Path that was expected to exist.
         */path: String
    )
    /**
     * A model-pack file does not hash to what the manifest claims.
     */
    case PackHashMismatch(
        /**
         * Manifest-relative file name.
         */file: String, 
        /**
         * Hex SHA-256 from the manifest.
         */expected: String, 
        /**
         * Hex SHA-256 actually computed.
         */actual: String
    )
    /**
     * The manifest or the label set is malformed.
     */
    case PackInvalid(
        /**
         * What was wrong; for logs only.
         */detail: String
    )
    /**
     * The cache DB is unusable.
     */
    case Cache(
        /**
         * SQLite message; for logs only.
         */detail: String
    )
    /**
     * The inference backend refused a model.
     */
    case Inference(
        /**
         * Backend message; for logs only.
         */detail: String
    )
    /**
     * A filesystem operation failed.
     */
    case Io(
        /**
         * The path involved.
         */path: String, 
        /**
         * Platform message; for logs only.
         */detail: String
    )
    /**
     * A sidecar could not be parsed or written.
     */
    case Sidecar(
        /**
         * Parser/writer message; for logs only.
         */detail: String
    )
    /**
     * The person's name cannot be used as one.
     *
     * Its own variant rather than a [`FaceError::Sidecar`]: this is the one
     * error a user can fix by typing something else, and the review UI shows
     * it next to the field rather than as a failure banner.
     */
    case InvalidName(
        /**
         * The name as typed.
         */name: String, 
        /**
         * Why it was rejected; shown to the user.
         */reason: String
    )
    /**
     * The cluster id is gone — a re-cluster pass rebuilt the partition under a
     * list the UI was still holding.
     */
    case ClusterNotFound(
        /**
         * The id that was not found.
         */id: Int64
    )
    /**
     * The merge would not produce a group: the two ids are the same.
     */
    case InvalidMerge(
        /**
         * What was wrong; for logs only.
         */detail: String
    )
    /**
     * The split selects nothing, or selects the whole cluster. Either leaves
     * the partition where it was while creating an empty or duplicate group.
     */
    case InvalidSplit(
        /**
         * What was wrong; for logs only.
         */detail: String
    )
    /**
     * A face key is not one this boundary handed out.
     *
     * Distinct from a key whose face is *gone*, which a split counts and skips
     * — the cache can move under a review screen the user left open.
     */
    case InvalidFaceKey(
        /**
         * The key as supplied.
         */key: String
    )
    /**
     * The run was cancelled.
     */
    case Cancelled
    /**
     * A run is in flight and this call refuses to share it. See the module
     * docs.
     */
    case AlreadyRunning

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FaceError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFaceError: FfiConverterRustBuffer {
    typealias SwiftType = FaceError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FaceError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .ModelsUnavailable
        case 2: return .PackFileMissing(
            path: try FfiConverterString.read(from: &buf)
            )
        case 3: return .PackHashMismatch(
            file: try FfiConverterString.read(from: &buf), 
            expected: try FfiConverterString.read(from: &buf), 
            actual: try FfiConverterString.read(from: &buf)
            )
        case 4: return .PackInvalid(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Cache(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Inference(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Io(
            path: try FfiConverterString.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Sidecar(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 9: return .InvalidName(
            name: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 10: return .ClusterNotFound(
            id: try FfiConverterInt64.read(from: &buf)
            )
        case 11: return .InvalidMerge(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 12: return .InvalidSplit(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 13: return .InvalidFaceKey(
            key: try FfiConverterString.read(from: &buf)
            )
        case 14: return .Cancelled
        case 15: return .AlreadyRunning

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FaceError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .ModelsUnavailable:
            writeInt(&buf, Int32(1))
        
        
        case let .PackFileMissing(path):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .PackHashMismatch(file,expected,actual):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(file, into: &buf)
            FfiConverterString.write(expected, into: &buf)
            FfiConverterString.write(actual, into: &buf)
            
        
        case let .PackInvalid(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Cache(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Inference(detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Io(path,detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(path, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Sidecar(detail):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .InvalidName(name,reason):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(name, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .ClusterNotFound(id):
            writeInt(&buf, Int32(10))
            FfiConverterInt64.write(id, into: &buf)
            
        
        case let .InvalidMerge(detail):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .InvalidSplit(detail):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .InvalidFaceKey(key):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(key, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(14))
        
        
        case .AlreadyRunning:
            writeInt(&buf, Int32(15))
        
        }
    }
}


